/**
 * 暇な間に止めるまでの時間を決める。0 なら止めない。
 * 常に動かす環境と、未完了の submission を確かめられないときは止めない
 */
export function idleTimeoutMs(options: {
	timeoutSeconds: number;
	alwaysOn: boolean;
	canProbe: boolean;
}): number {
	if (options.alwaysOn || !options.canProbe) return 0;
	return options.timeoutSeconds * 1000;
}

export type IdleMonitorOptions = {
	/** 要求がなくなってから止めるまでの時間。0 なら止めない */
	timeoutMs: number;
	/** 処理中の HTTP 要求の数 */
	inFlight: () => number;
	/**
	 * 未完了の submission があるかを返す。
	 * 判定できないときは undefined を返し、その場合は止めない。
	 */
	hasUnsettled: () => Promise<boolean | undefined>;
	onIdle: () => void;
	/** 判定の間隔。既定は timeoutMs の 4 分の 1 で、15 秒から 60 秒の間に収める */
	checkIntervalMs?: number;
	now?: () => number;
};

export type IdleMonitor = {
	/** 要求が来たときに呼ぶ */
	touch(): void;
	/** 1 回判定する。止める条件を満たしたら true を返す */
	check(): Promise<boolean>;
	stop(): void;
};

/**
 * 要求がなく、未完了の submission もない状態が続いたら onIdle を呼ぶ。
 * Flue は 202 を返したあとも裏でエージェントを動かすので、HTTP の静けさだけでは止めない。
 */
export function createIdleMonitor(options: IdleMonitorOptions): IdleMonitor {
	const now = options.now ?? Date.now;
	let lastActivity = now();
	let timer: ReturnType<typeof setInterval> | undefined;
	let checking = false;
	let fired = false;

	const check = async (): Promise<boolean> => {
		if (fired || checking || options.timeoutMs <= 0) return false;
		if (options.inFlight() > 0) {
			lastActivity = now();
			return false;
		}
		if (now() - lastActivity < options.timeoutMs) return false;
		checking = true;
		try {
			let unsettled: boolean | undefined;
			try {
				unsettled = await options.hasUnsettled();
			} catch {
				unsettled = undefined;
			}
			if (unsettled !== false) {
				// 処理中の仕事があるか、判定できなかった。次の周期にもう一度確かめる
				return false;
			}
			// 問い合わせの間に要求が来ていたら止めない
			if (options.inFlight() > 0 || now() - lastActivity < options.timeoutMs) {
				return false;
			}
			fired = true;
			if (timer) clearInterval(timer);
			options.onIdle();
			return true;
		} finally {
			checking = false;
		}
	};

	if (options.timeoutMs > 0) {
		const interval =
			options.checkIntervalMs ??
			Math.min(60_000, Math.max(15_000, Math.floor(options.timeoutMs / 4)));
		timer = setInterval(() => {
			void check();
		}, interval);
		timer.unref();
	}

	return {
		touch() {
			lastActivity = now();
		},
		check,
		stop() {
			if (timer) clearInterval(timer);
			timer = undefined;
		},
	};
}

/** 応答の終わりを知らせるもの。node:http の ServerResponse がこれを満たす */
export type ResponseCloseEmitter = {
	once(event: "close", listener: () => void): unknown;
};

export type AdmissionTracker = {
	/** 処理中の要求の数 */
	inFlight(): number;
	/** 検査を通った要求を数え始める。応答が閉じたら数から外す */
	admit(outgoing: ResponseCloseEmitter | undefined): void;
};

/**
 * アクセスの検査を通った要求だけを数え、そのたびに onActivity を呼ぶ。
 * ヘルスチェックや拒んだ要求でアイドル停止を先送りさせないために、検査のあとで呼ぶ
 */
export function createAdmissionTracker(
	onActivity: () => void,
): AdmissionTracker {
	let inFlight = 0;
	return {
		inFlight: () => inFlight,
		admit(outgoing) {
			onActivity();
			// 応答の終わりを知る手段がなければ、数えずに活動だけを記録する
			if (!outgoing) return;
			inFlight += 1;
			outgoing.once("close", () => {
				inFlight -= 1;
				onActivity();
			});
		},
	};
}
