import { createReadStream, type Stats } from "node:fs";
import { stat } from "node:fs/promises";
import type { IncomingMessage, ServerResponse } from "node:http";
import { extname, join, resolve, sep } from "node:path";

/** 名前にハッシュの入ったファイルに付ける見出し。入口がこの応答だけをキャッシュする */
export const IMMUTABLE_CACHE_CONTROL = "public, max-age=31536000, immutable";

/** HTML とハッシュのないファイルに付ける見出し。毎回確かめさせ、デプロイの切り替えをすぐ届ける */
export const REVALIDATE_CACHE_CONTROL = "no-cache";

export type StaticHandlerOptions = {
	/** 配信するディレクトリの絶対パス */
	root: string;
	/** この接頭辞の下のファイルを、名前にハッシュの入ったファイルとして扱う */
	immutablePrefixes: readonly string[];
	/** immutablePrefixes の下でも、ハッシュの入らないファイルを置く接頭辞 */
	mutablePrefixes?: readonly string[];
	/**
	 * ファイルがないときと、GET と HEAD でない要求を渡す先。SSR のサーバーを置く。
	 * あれば SPA の戻り先と 404 と 405 は返さない
	 */
	fallthrough?: NodeHandler;
};

export type NodeHandler = (
	request: IncomingMessage,
	response: ServerResponse,
) => Promise<void>;

const CONTENT_TYPES: Record<string, string> = {
	".html": "text/html; charset=utf-8",
	".htm": "text/html; charset=utf-8",
	".js": "text/javascript; charset=utf-8",
	".mjs": "text/javascript; charset=utf-8",
	".css": "text/css; charset=utf-8",
	".json": "application/json; charset=utf-8",
	".map": "application/json; charset=utf-8",
	".webmanifest": "application/manifest+json; charset=utf-8",
	".txt": "text/plain; charset=utf-8",
	".xml": "application/xml; charset=utf-8",
	".svg": "image/svg+xml",
	".png": "image/png",
	".jpg": "image/jpeg",
	".jpeg": "image/jpeg",
	".gif": "image/gif",
	".webp": "image/webp",
	".avif": "image/avif",
	".ico": "image/x-icon",
	".woff": "font/woff",
	".woff2": "font/woff2",
	".ttf": "font/ttf",
	".otf": "font/otf",
	".wasm": "application/wasm",
	".pdf": "application/pdf",
	".mp4": "video/mp4",
	".webm": "video/webm",
	".mp3": "audio/mpeg",
};

/** 圧縮済みのファイルの拡張子。良いものから順に選ぶ */
const ENCODINGS = [
	{ name: "br", suffix: ".br" },
	{ name: "gzip", suffix: ".gz" },
] as const;

/** SPA の戻り先。Nuxt の nuxt generate は 200.html を、Vite は index.html を出す */
const SPA_FALLBACKS = ["200.html", "index.html"];

function contentType(path: string): string {
	return (
		CONTENT_TYPES[extname(path).toLowerCase()] ?? "application/octet-stream"
	);
}

/** Accept-Encoding が encoding を受け付けるか。q=0 は断りとみなす */
export function acceptsEncoding(
	header: string | undefined,
	encoding: string,
): boolean {
	if (!header) return false;
	for (const part of header.split(",")) {
		const [name, ...params] = part.trim().toLowerCase().split(";");
		if (name?.trim() !== encoding) continue;
		const q = params
			.map((param) => param.trim())
			.find((param) => param.startsWith("q="));
		return q === undefined || Number(q.slice(2)) > 0;
	}
	return false;
}

async function fileStats(path: string): Promise<Stats | undefined> {
	try {
		const stats = await stat(path);
		return stats.isFile() ? stats : undefined;
	} catch {
		return undefined;
	}
}

/**
 * 要求のパスを、root の中のファイルのパスにする。root の外を指すもの、隠しファイル、読めない符号は undefined を返す。
 * `/.well-known/` だけは隠しファイルでも配る
 */
export function resolveStaticPath(
	root: string,
	rawPath: string,
): string | undefined {
	let pathname: string;
	try {
		pathname = decodeURIComponent(rawPath);
	} catch {
		return undefined;
	}
	if (pathname.includes("\0") || pathname.includes("\\")) return undefined;
	const segments = pathname.split("/").filter((segment) => segment !== "");
	for (const [index, segment] of segments.entries()) {
		if (segment === "." || segment === "..") return undefined;
		if (
			segment.startsWith(".") &&
			!(index === 0 && segment === ".well-known")
		) {
			return undefined;
		}
	}
	const absolute = resolve(root, ...segments);
	if (absolute !== root && !absolute.startsWith(`${root}${sep}`)) {
		return undefined;
	}
	return absolute;
}

/** 要求の行からパスを取り出す。クエリを除き、復号はしない */
export function requestPath(request: IncomingMessage): string {
	const raw = request.url ?? "/";
	if (raw.startsWith("/")) return raw.split("?")[0] ?? "/";
	try {
		return new URL(raw).pathname;
	} catch {
		return "/";
	}
}

type Found = { path: string; stats: Stats; fallback: boolean };

/** パスに当たるファイルを探す。ディレクトリなら index.html、拡張子がなければ .html を足したものも見る */
async function findFile(
	root: string,
	pathname: string,
): Promise<Found | undefined> {
	const target = resolveStaticPath(root, pathname);
	if (!target) return undefined;
	const candidates = [target, join(target, "index.html")];
	if (extname(target) === "") candidates.push(`${target}.html`);
	for (const candidate of candidates) {
		const stats = await fileStats(candidate);
		if (stats) return { path: candidate, stats, fallback: false };
	}
	return undefined;
}

/** 拡張子のないパスはページとみなし、SPA の戻り先を返す。ファイルらしいパスには返さない */
async function findFallback(
	root: string,
	pathname: string,
): Promise<Found | undefined> {
	if (extname(pathname) !== "") return undefined;
	for (const name of SPA_FALLBACKS) {
		const path = join(root, name);
		const stats = await fileStats(path);
		if (stats) return { path, stats, fallback: true };
	}
	return undefined;
}

function sendText(
	response: ServerResponse,
	status: number,
	body: string,
	headers: Record<string, string> = {},
): void {
	response.writeHead(status, {
		"content-type": "text/plain; charset=utf-8",
		"cache-control": "no-store",
		...headers,
	});
	response.end(body);
}

/**
 * ビルドしたフロントエンドの静的なファイルを返す Node の handler を作る。
 * 圧縮済みの .br と .gz があれば Accept-Encoding に合わせて返し、ハッシュの入ったファイルには immutable を付ける。
 * 見つからないページのパスには、SPA の戻り先の HTML を 200 で返す。
 * fallthrough があれば、見つからない要求をそこへ渡す
 */
export function createStaticHandler(
	options: StaticHandlerOptions,
): NodeHandler {
	const root = resolve(options.root);
	const mutablePrefixes = options.mutablePrefixes ?? [];
	const isImmutable = (pathname: string) =>
		options.immutablePrefixes.some((prefix) => pathname.startsWith(prefix)) &&
		!mutablePrefixes.some((prefix) => pathname.startsWith(prefix));

	return async (request, response) => {
		const { fallthrough } = options;
		if (request.method !== "GET" && request.method !== "HEAD") {
			if (fallthrough) return fallthrough(request, response);
			sendText(response, 405, "method not allowed\n", { allow: "GET, HEAD" });
			return;
		}
		const pathname = requestPath(request);
		const file = await findFile(root, pathname);
		if (!file && fallthrough) return fallthrough(request, response);
		const found = file ?? (await findFallback(root, pathname));
		if (!found) {
			const notFound = await fileStats(join(root, "404.html"));
			if (notFound && extname(pathname) === "") {
				await sendFile(request, response, {
					path: join(root, "404.html"),
					stats: notFound,
					status: 404,
					cacheControl: REVALIDATE_CACHE_CONTROL,
				});
				return;
			}
			sendText(response, 404, "not found\n");
			return;
		}
		const cacheControl =
			!found.fallback &&
			isImmutable(pathname) &&
			extname(found.path) !== ".html"
				? IMMUTABLE_CACHE_CONTROL
				: REVALIDATE_CACHE_CONTROL;
		await sendFile(request, response, {
			path: found.path,
			stats: found.stats,
			status: 200,
			cacheControl,
		});
	};
}

async function sendFile(
	request: IncomingMessage,
	response: ServerResponse,
	file: { path: string; stats: Stats; status: number; cacheControl: string },
): Promise<void> {
	const acceptEncoding = request.headers["accept-encoding"];
	let servedPath = file.path;
	let servedSize = file.stats.size;
	let encoding: string | undefined;
	for (const candidate of ENCODINGS) {
		if (!acceptsEncoding(acceptEncoding, candidate.name)) continue;
		const stats = await fileStats(`${file.path}${candidate.suffix}`);
		if (!stats) continue;
		servedPath = `${file.path}${candidate.suffix}`;
		servedSize = stats.size;
		encoding = candidate.name;
		break;
	}
	const etag = `W/"${file.stats.size.toString(16)}-${Math.floor(file.stats.mtimeMs).toString(16)}${encoding ? `-${encoding}` : ""}"`;
	const headers: Record<string, string | number> = {
		"content-type": contentType(file.path),
		"cache-control": file.cacheControl,
		// 圧縮の有無で中身が変わる。入口のキャッシュは vary が accept-encoding だけの応答を受け付ける
		vary: "accept-encoding",
		etag,
		"last-modified": file.stats.mtime.toUTCString(),
		"x-content-type-options": "nosniff",
	};
	if (encoding) headers["content-encoding"] = encoding;
	if (file.status === 200 && request.headers["if-none-match"] === etag) {
		response.writeHead(304, headers);
		response.end();
		return;
	}
	headers["content-length"] = servedSize;
	response.writeHead(file.status, headers);
	if (request.method === "HEAD") {
		response.end();
		return;
	}
	await new Promise<void>((resolveSent) => {
		const stream = createReadStream(servedPath);
		stream.once("error", () => {
			response.destroy();
			resolveSent();
		});
		response.once("close", () => {
			stream.destroy();
			resolveSent();
		});
		stream.pipe(response);
	});
}
