import { monitorEventLoopDelay } from "node:perf_hooks";
import type { Logger } from "@rouar/log";

export type EventLoopLagOptions = {
	logger: Logger;
	/** この長さを超えて止まった周期だけを記録する */
	thresholdMs?: number;
	/** 集計の周期 */
	intervalMs?: number;
};

/** 既定の閾値。SSR の 1 回の描画やエージェントの処理で、これより長く止まるのはまれ */
const DEFAULT_THRESHOLD_MS = 500;
const DEFAULT_INTERVAL_MS = 30_000;

/**
 * イベントループの遅れを測り、閾値を超えた周期の最大と p99 をログに残す。
 * フロントエンドとエージェントが同じプロセスで動くので、片方の重い処理がもう片方を止めたことを後で追えるようにする
 */
export function startEventLoopLagMonitor(options: EventLoopLagOptions): {
	stop(): void;
} {
	const thresholdMs = options.thresholdMs ?? DEFAULT_THRESHOLD_MS;
	const histogram = monitorEventLoopDelay({ resolution: 20 });
	histogram.enable();
	const timer = setInterval(() => {
		const maxMs = histogram.max / 1e6;
		if (maxMs >= thresholdMs) {
			options.logger.warn(
				{
					maxMs: Math.round(maxMs),
					p99Ms: Math.round(histogram.percentile(99) / 1e6),
					meanMs: Math.round(histogram.mean / 1e6),
				},
				"event loop was blocked",
			);
		}
		histogram.reset();
	}, options.intervalMs ?? DEFAULT_INTERVAL_MS);
	timer.unref();
	return {
		stop() {
			clearInterval(timer);
			histogram.disable();
		},
	};
}
