import { createHmac, randomBytes } from "node:crypto";
import { AppError, PROBLEM_CONTENT_TYPE, toProblem } from "@rouar/error";
import type { Logger } from "@rouar/log";
import {
	type BrowserAuthorize,
	type BrowserAuthorizeContext,
	getBrowserAuthorize,
	isValidPrincipal,
	PRINCIPAL_HEADER,
} from "../access";
import { matchesPathPrefix } from "./gate";

export { isValidPrincipal, PRINCIPAL_HEADER };

/** 書き換えたあとの会話の id の接頭辞の形。rv_ と 16 桁の 16 進と _ */
const NAMESPACED_ID = /^rv_([0-9a-f]{16})_/;

/** 鍵を導くときの文脈。値を変えると、すべての会話の id が変わる */
const TAG_KEY_CONTEXT = "rouar browser conversation tag v1";

const MINUTE_MS = 60_000;
const DAY_MS = 86_400_000;

function problem(
	request: Request,
	status: number,
	code: string,
	title: string,
	detail?: string,
	headers: Record<string, string> = {},
): Response {
	const body = toProblem(
		new AppError(status, code, title, detail === undefined ? {} : { detail }),
		new URL(request.url).pathname,
	);
	return new Response(JSON.stringify(body), {
		status,
		headers: {
			"content-type": PROBLEM_CONTENT_TYPE,
			"cache-control": "no-store",
			...headers,
		},
	});
}

/** 要求から、利用者が送った呼び出し元の見出しを外す。ヘッダーを変えられない要求は作り直す */
export function withoutPrincipalHeader(request: Request): Request {
	if (!request.headers.has(PRINCIPAL_HEADER)) return request;
	try {
		request.headers.delete(PRINCIPAL_HEADER);
		if (!request.headers.has(PRINCIPAL_HEADER)) return request;
	} catch {
		// 変えられないヘッダーなら、下で作り直す
	}
	const next = new Request(request);
	next.headers.delete(PRINCIPAL_HEADER);
	return next;
}

/** 会話の URL を分けた結果。segments は接頭辞のあとの区切り */
export type ConversationPath = {
	/** 接頭辞と mount の名前までのパス。末尾の / を含まない */
	base: string;
	/** 会話の id の、パスに書かれたままの区切り */
	id: string;
	/** id のあとのパス。空か、/abort か、/attachments/<id> */
	tail: string;
};

/** パスの区切りに使えない値。符号化した / と \ と、. と .. を断り、ルーターとの解釈の違いをなくす */
function unsafeSegment(segment: string): boolean {
	return (
		segment === "" ||
		segment === "." ||
		segment === ".." ||
		/%2f|%5c/i.test(segment)
	);
}

/**
 * パスが Flue の会話の URL かを確かめて分ける。
 * <接頭辞>/<mount の名前>/<会話の id> と、そのあとの /abort と /attachments/<id> だけを会話の URL とみなす
 */
export function parseConversationPath(
	pathname: string,
	agentRoutes: readonly string[],
): ConversationPath | undefined {
	for (const route of agentRoutes) {
		if (!matchesPathPrefix(pathname, route)) continue;
		const normalized = route.startsWith("/") ? route : `/${route}`;
		const prefix = normalized.endsWith("/")
			? normalized.slice(0, -1)
			: normalized;
		const rest = pathname.slice(prefix.length).split("/");
		// rest[0] は接頭辞の直後の空の区切り
		const [, name, id, ...tail] = rest;
		if (name === undefined || id === undefined) continue;
		if (unsafeSegment(name) || unsafeSegment(id)) continue;
		const tailPath = tail.length === 0 ? "" : `/${tail.join("/")}`;
		const knownTail =
			tail.length === 0 ||
			(tail.length === 1 && tail[0] === "abort") ||
			(tail.length === 2 &&
				tail[0] === "attachments" &&
				!unsafeSegment(tail[1] as string));
		if (!knownTail) continue;
		return { base: `${prefix}/${name}`, id, tail: tailPath };
	}
	return undefined;
}

/**
 * 呼び出し元から会話の id の tag を作る関数を作る。
 * 鍵の材料は、環境ごとに変わらない値を使う。デプロイのたびに変わる値を使うと、前の会話を読めなくなる
 */
export function createConversationTagger(
	keyMaterial: string,
): (principal: string) => string {
	const key = createHmac("sha256", keyMaterial)
		.update(TAG_KEY_CONTEXT)
		.digest();
	return (principal) =>
		createHmac("sha256", key)
			.update(principal, "utf8")
			.digest("hex")
			.slice(0, 16);
}

/**
 * 会話の id を呼び出し元の tag で分けた要求を作る。別の呼び出し元の id なら 404 の応答を返す。
 * すでに同じ tag の id なら書き換えない。応答の streamUrl に入った id でそのまま呼べるようにするため
 */
export function namespaceConversation(
	request: Request,
	conversation: ConversationPath,
	tag: string,
	principal: string,
): Request | Response {
	const owned = NAMESPACED_ID.exec(conversation.id);
	if (owned && owned[1] !== tag) {
		return problem(request, 404, "not_found", "Not Found");
	}
	const url = new URL(request.url);
	if (!owned) {
		url.pathname = `${conversation.base}/rv_${tag}_${conversation.id}${conversation.tail}`;
	}
	const next =
		url.href === request.url ? new Request(request) : new Request(url, request);
	next.headers.set(PRINCIPAL_HEADER, principal);
	return next;
}

/** 状態を変える要求か。GET と HEAD と OPTIONS のほかを CSRF の確かめの対象にする */
function changesState(method: string): boolean {
	return method !== "GET" && method !== "HEAD" && method !== "OPTIONS";
}

/**
 * ほかのオリジンからの送信を断る。Sec-Fetch-Site があれば same-origin だけを、
 * なければ Origin が要求の URL のオリジンと同じものだけを受ける。どちらもなければ断る。
 * 要求の URL は、入口のトークンを確かめた要求なら X-Forwarded-Host から組み立て直してある
 */
export function checkSameOrigin(request: Request): Response | undefined {
	if (!changesState(request.method)) return undefined;
	const site = request.headers.get("sec-fetch-site");
	if (site !== null) {
		if (site.trim().toLowerCase() === "same-origin") return undefined;
		return forbiddenOrigin(request);
	}
	const origin = request.headers.get("origin");
	if (origin !== null && origin !== "null") {
		try {
			if (new URL(origin).origin === new URL(request.url).origin) {
				return undefined;
			}
		} catch {
			// 形の違う Origin は断る
		}
	}
	return forbiddenOrigin(request);
}

function forbiddenOrigin(request: Request): Response {
	return problem(
		request,
		403,
		"cross_origin_request",
		"Forbidden",
		"Browser requests to the agent must come from the same origin.",
	);
}

/** 本文を持つ要求か。Content-Length が 0 でなく、または Transfer-Encoding があれば持つとみなす */
function hasBody(request: Request): boolean {
	const length = request.headers.get("content-length");
	if (request.headers.has("transfer-encoding")) return true;
	if (length !== null) return length.trim() !== "0";
	return request.body !== null;
}

/**
 * POST の本文を application/json に限る。form から送れる形を断るため。
 * 本文のない POST は、会話を止める /abort のために受ける
 */
export function checkJsonBody(request: Request): Response | undefined {
	if (request.method !== "POST") return undefined;
	const type = request.headers.get("content-type");
	const media = type?.split(";")[0]?.trim().toLowerCase();
	if (media === "application/json") return undefined;
	if (type === null && !hasBody(request)) return undefined;
	return problem(
		request,
		415,
		"unsupported_media_type",
		"Unsupported Media Type",
		"Send the request body as application/json.",
	);
}

export type SendLimits = {
	perMinute: number;
	perDay: number;
	environmentPerDay: number;
};

type Counter = { window: number; count: number };

/**
 * 呼び出し元ごとと環境の全体の送信を、固定の窓で数える。マシンが止まると数はなくなる。
 * 超えたら、次の窓までの秒数を返す
 */
export function createSendLimiter(
	limits: SendLimits,
	now: () => number = Date.now,
): (principal: string) => { retryAfterSeconds: number } | undefined {
	const minutes = new Map<string, Counter>();
	const days = new Map<string, Counter>();
	let environment: Counter = { window: -1, count: 0 };
	let sweptMinute = -1;

	const bump = (
		map: Map<string, Counter>,
		key: string,
		window: number,
	): Counter => {
		const current = map.get(key);
		if (current && current.window === window) return current;
		const fresh = { window, count: 0 };
		map.set(key, fresh);
		return fresh;
	};

	return (principal) => {
		const at = now();
		const minute = Math.floor(at / MINUTE_MS);
		const day = Math.floor(at / DAY_MS);
		// 古い窓の数を捨て、呼び出し元が増え続けてもメモリが増え続けないようにする
		if (sweptMinute !== minute) {
			sweptMinute = minute;
			for (const [key, counter] of minutes) {
				if (counter.window !== minute) minutes.delete(key);
			}
			for (const [key, counter] of days) {
				if (counter.window !== day) days.delete(key);
			}
		}
		if (environment.window !== day) environment = { window: day, count: 0 };
		const untilNextMinute = Math.ceil(((minute + 1) * MINUTE_MS - at) / 1000);
		const untilNextDay = Math.ceil(((day + 1) * DAY_MS - at) / 1000);

		const perMinute = bump(minutes, principal, minute);
		const perDay = bump(days, principal, day);
		if (environment.count >= limits.environmentPerDay) {
			return { retryAfterSeconds: untilNextDay };
		}
		if (perDay.count >= limits.perDay) {
			return { retryAfterSeconds: untilNextDay };
		}
		if (perMinute.count >= limits.perMinute) {
			return { retryAfterSeconds: untilNextMinute };
		}
		perMinute.count += 1;
		perDay.count += 1;
		environment.count += 1;
		return undefined;
	};
}

export type BrowserAccessOptions = {
	/** 会話の URL の接頭辞。rouar.json の agent.routes */
	agentRoutes: readonly string[];
	/** 会話の id の tag を作る鍵の材料。環境ごとに変わらない値 */
	tagKey: string;
	limits: SendLimits;
	logger: Logger;
	/** 許可の関数を返す。既定は allowBrowserAgents の登録先 */
	authorize?: () => BrowserAuthorize | undefined;
	now?: () => number;
};

/** ブラウザの要求を通すときに Flue に渡す要求と、応答を整える関数 */
export type BrowserAdmission = {
	request: Request;
	finish: (response: Response) => Response;
};

export type BrowserAccess = {
	/**
	 * アクセストークンも公開の設定もない要求を、許可の関数で確かめる。
	 * 許可の関数がないか、会話の URL でなければ undefined を返し、今までどおり 401 にさせる
	 */
	admit(
		request: Request,
		context: BrowserAuthorizeContext,
	): Promise<BrowserAdmission | Response | undefined>;
	/** agentFetch で、サーバーのコードが渡した呼び出し元で会話を分ける */
	scope(request: Request, principal: string | undefined): Request | Response;
};

/** SSE の応答をキャッシュさせない */
function noStoreStream(response: Response): Response {
	const type = response.headers.get("content-type") ?? "";
	if (!type.toLowerCase().startsWith("text/event-stream")) return response;
	const next = new Response(response.body, response);
	next.headers.set("cache-control", "no-store");
	return next;
}

/** 本文を持たない写し。許可の関数に本文を読ませない */
function withoutBody(request: Request): Request {
	return new Request(request.url, {
		method: request.method,
		headers: request.headers,
		signal: request.signal,
	});
}

export function createBrowserAccess(
	options: BrowserAccessOptions,
): BrowserAccess {
	const tagOf = createConversationTagger(options.tagKey);
	const limit = createSendLimiter(options.limits, options.now);
	const readAuthorize = options.authorize ?? getBrowserAuthorize;

	return {
		async admit(request, context) {
			const authorize = readAuthorize();
			if (!authorize) return undefined;
			const conversation = parseConversationPath(
				new URL(request.url).pathname,
				options.agentRoutes,
			);
			if (!conversation) return undefined;
			// 利用者の関数を呼ぶ前に、ほかのオリジンからの送信と form の形を断る
			const crossOrigin = checkSameOrigin(request);
			if (crossOrigin) return crossOrigin;
			const notJson = checkJsonBody(request);
			if (notJson) return notJson;

			let result: Awaited<ReturnType<BrowserAuthorize>>;
			try {
				result = await authorize(withoutBody(request), context);
			} catch (error) {
				options.logger.error(
					{ err: error },
					"the browser authorize function threw",
				);
				return problem(request, 500, "internal", "Internal server error");
			}
			if (result === null || result === undefined) return undefined;
			if (!isValidPrincipal(result.principal)) {
				// 値そのものは記録しない
				options.logger.error(
					"the browser authorize function returned an invalid principal; use 1 to 256 printable ASCII characters",
				);
				return problem(request, 500, "internal", "Internal server error");
			}
			const principal = result.principal;
			const scoped = namespaceConversation(
				request,
				conversation,
				tagOf(principal),
				principal,
			);
			if (scoped instanceof Response) return scoped;
			// 送信は会話の URL への POST。読み取りと SSE と /abort は数えない
			if (request.method === "POST" && conversation.tail === "") {
				const limited = limit(principal);
				if (limited) {
					return problem(
						request,
						429,
						"too_many_requests",
						"Too Many Requests",
						"Too many messages were sent from this browser. Try again later.",
						{ "retry-after": String(limited.retryAfterSeconds) },
					);
				}
			}
			return { request: scoped, finish: noStoreStream };
		},

		scope(request, principal) {
			const stripped = withoutPrincipalHeader(request);
			if (principal === undefined) return stripped;
			if (!isValidPrincipal(principal)) {
				throw new TypeError(
					"[rouar] agentFetch() principal must be 1 to 256 printable ASCII characters.",
				);
			}
			const conversation = parseConversationPath(
				new URL(stripped.url).pathname,
				options.agentRoutes,
			);
			if (!conversation) {
				const next = new Request(stripped);
				next.headers.set(PRINCIPAL_HEADER, principal);
				return next;
			}
			return namespaceConversation(
				stripped,
				conversation,
				tagOf(principal),
				principal,
			);
		},
	};
}

/**
 * 会話の id の tag を作る鍵の材料を選ぶ。デプロイのたびに変わる ROUAR_TOKEN は使わない。
 * 入口のトークンは環境のラベルから導かれ、変わらず、秘密なので先に使う。
 * なければ環境の id を使い、それもなければプロセスごとの乱数にする
 */
export function selectTagKey(
	env: {
		ROUAR_EDGE_TOKEN?: string | undefined;
		ROUAR_ENVIRONMENT_ID?: string | undefined;
	},
	logger: Logger,
): string {
	const edge = env.ROUAR_EDGE_TOKEN?.trim();
	if (edge) return `edge:${edge}`;
	const environment = env.ROUAR_ENVIRONMENT_ID?.trim();
	if (environment) return `environment:${environment}`;
	logger.debug(
		"no stable key for browser conversation ids; browser conversations are kept only until the server restarts",
	);
	return `process:${randomBytes(32).toString("hex")}`;
}
