import { createHash, timingSafeEqual } from "node:crypto";

/**
 * 入口が付けるトークンのヘッダー。apps/edge の EDGE_TOKEN_HEADER と同じ名前にする。
 * 値は HMAC-SHA256(EDGE_TENANT_KEY, <ラベル>) の 16 進表記で、ワーカーが同じ値を ROUAR_EDGE_TOKEN に入れる
 */
export const EDGE_TOKEN_HEADER = "x-rouar-edge-token";

function sha256(value: string): Buffer {
	return createHash("sha256").update(value, "utf8").digest();
}

/**
 * 入口を通った要求かを判定する関数を作る。
 * トークンがなければ、すべての要求を通す。トークンを入れる前にデプロイしたアプリを壊さないため。
 * 長さの違いで比較の時間が変わらないよう、両方のハッシュを比べる
 */
export function createEdgeCheck(
	token: string | undefined,
): (request: Request) => boolean {
	const matches = createEdgeTokenMatcher(token);
	return (request) => matches(request.headers.get(EDGE_TOKEN_HEADER));
}

/** 入口のトークンのヘッダーの値を比べる関数を作る。Fetch の要求と Node の要求の両方で使う */
function createEdgeTokenMatcher(
	token: string | undefined,
): (received: string | null | undefined) => boolean {
	const expected = token?.trim();
	if (!expected) return () => true;
	const expectedDigest = sha256(expected);
	return (received) => {
		if (received === null || received === undefined) return false;
		return timingSafeEqual(sha256(received.trim()), expectedDigest);
	};
}

/** 入口を通っていない要求への応答。アプリの有無も実行基盤の名前も示さない */
export function edgeNotFound(): Response {
	return new Response("not found\n", {
		status: 404,
		headers: {
			"content-type": "text/plain; charset=utf-8",
			"cache-control": "no-store",
		},
	});
}

/** 利用者のコードに渡す前に、入口のトークンを外す。ヘッダーを変えられない要求は作り直す */
export function withoutEdgeToken(request: Request): Request {
	if (!request.headers.has(EDGE_TOKEN_HEADER)) return request;
	try {
		request.headers.delete(EDGE_TOKEN_HEADER);
		if (!request.headers.has(EDGE_TOKEN_HEADER)) return request;
	} catch {
		// 変えられないヘッダーなら、下で作り直す
	}
	const headers = new Headers(request.headers);
	headers.delete(EDGE_TOKEN_HEADER);
	return new Request(request, { headers });
}

/**
 * 入口が付ける、利用者が見たホストと scheme のヘッダー。
 * apps/edge の forwardRequestHeaders が、利用者の送った値を捨ててから付け直す
 */
export const FORWARDED_HOST_HEADER = "x-forwarded-host";
export const FORWARDED_PROTO_HEADER = "x-forwarded-proto";

/** 点で区切った DNS のラベルだけを受ける。ポート、パス、利用者情報、複数の値を含む値は通さない */
const FORWARDED_HOST =
	/^(?=.{1,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$/;
const FORWARDED_PROTOS = new Set(["https", "http"]);

/** 転送のヘッダーの値を確かめ、小文字にしたホストと scheme を返す。形式が違えば undefined を返す */
function forwardedOrigin(
	hostHeader: string | null | undefined,
	protoHeader: string | null | undefined,
): { host: string; proto: string } | undefined {
	const host = hostHeader?.trim().toLowerCase();
	const proto = protoHeader?.trim().toLowerCase();
	if (!host || !proto) return undefined;
	if (!FORWARDED_HOST.test(host) || !FORWARDED_PROTOS.has(proto)) {
		return undefined;
	}
	return { host, proto };
}

/**
 * 入口のヘッダーから、利用者が送った URL を組み立てる。パスとクエリは要求のものを使う。
 * ヘッダーがないか、形式が違えば undefined を返す
 */
export function forwardedUrl(request: Request): URL | undefined {
	const forwarded = forwardedOrigin(
		request.headers.get(FORWARDED_HOST_HEADER),
		request.headers.get(FORWARDED_PROTO_HEADER),
	);
	if (!forwarded) return undefined;
	const { host, proto } = forwarded;
	const url = new URL(request.url);
	url.protocol = `${proto}:`;
	url.hostname = host;
	url.port = "";
	url.username = "";
	url.password = "";
	// URL の正規化で値が変わったら使わない
	if (url.hostname !== host || url.protocol !== `${proto}:`) return undefined;
	return url;
}

/**
 * 要求の URL を、入口のヘッダーが示す利用者側の URL に置き換える。
 * Flue は要求の URL から streamUrl と Location を作るので、置き換えないと実行基盤のホストが利用者に見える。
 * 入口のトークンを確かめた要求にだけ使う
 */
export function withForwardedUrl(request: Request): Request {
	const url = forwardedUrl(request);
	if (!url || url.href === request.url) return request;
	return new Request(url, request);
}

/**
 * 入口を通った要求を、利用者のコードに渡す形にする関数を作る。入口を通っていなければ undefined を返す。
 * トークンがあれば、トークンを確かめた要求でだけ、転送のヘッダーから URL を組み立て直す。
 * トークンがなければ、だれでも転送のヘッダーを付けられるので、URL は変えない
 */
export function createEdgeAdmission(
	token: string | undefined,
): (request: Request) => Request | undefined {
	const check = createEdgeCheck(token);
	const verified = Boolean(token?.trim());
	return (request) => {
		if (!check(request)) return undefined;
		const stripped = withoutEdgeToken(request);
		return verified ? withForwardedUrl(stripped) : stripped;
	};
}

/** Node の要求のうち、入口の検査で読み書きするもの。node:http の IncomingMessage がこれを満たす */
export type NodeEdgeRequest = {
	headers: Record<string, string | string[] | undefined>;
	rawHeaders: string[];
};

function singleHeader(
	value: string | string[] | undefined,
): string | undefined {
	return Array.isArray(value) ? value.join(", ") : value;
}

/**
 * createEdgeAdmission の Node の要求の版。フロントエンドの listener に渡す前に使う。
 * 入口を通っていなければ false を返す。通っていれば、要求のヘッダーをその場で書き換えて true を返す。
 * トークンのヘッダーを外し、トークンがあれば Host を転送のヘッダーのホストに置き換える。
 * Nitro は Host と X-Forwarded-Proto から要求の URL を組み立てるので、Flue の streamUrl と同じく利用者側の URL になる
 */
export function createNodeEdgeAdmission(
	token: string | undefined,
): (request: NodeEdgeRequest) => boolean {
	const matches = createEdgeTokenMatcher(token);
	const verified = Boolean(token?.trim());
	return (request) => {
		if (!matches(singleHeader(request.headers[EDGE_TOKEN_HEADER])))
			return false;
		const forwarded = verified
			? forwardedOrigin(
					singleHeader(request.headers[FORWARDED_HOST_HEADER]),
					singleHeader(request.headers[FORWARDED_PROTO_HEADER]),
				)
			: undefined;
		delete request.headers[EDGE_TOKEN_HEADER];
		if (forwarded) request.headers.host = forwarded.host;
		// rawHeaders から Headers を作る実装もあるので、同じ書き換えを rawHeaders にもする
		const raw: string[] = [];
		for (let index = 0; index + 1 < request.rawHeaders.length; index += 2) {
			const name = request.rawHeaders[index] as string;
			const value = request.rawHeaders[index + 1] as string;
			const lower = name.toLowerCase();
			if (lower === EDGE_TOKEN_HEADER) continue;
			if (forwarded && lower === "host") continue;
			raw.push(name, value);
		}
		if (forwarded) raw.push("Host", forwarded.host);
		request.rawHeaders.splice(0, request.rawHeaders.length, ...raw);
		return true;
	};
}
