import { createHash, timingSafeEqual } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import { AppError, PROBLEM_CONTENT_TYPE, toProblem } from "@rouar/error";
import type { BrowserAuthorizeContext } from "../access";
import { type BrowserAccess, withoutPrincipalHeader } from "./browser";
import { edgeNotFound, withoutEdgeToken } from "./edge";

/** 常に公開するヘルスチェックのパス */
export const HEALTH_PATH = "/_rouar/health";

export type AccessGateOptions = {
	/** デプロイのアクセストークンの SHA-256 の 16 進表記 */
	tokenHashes: readonly string[];
	/** true なら検査をしない */
	public: boolean;
	/** 検査をしないパスの接頭辞 */
	publicPaths: readonly string[];
};

const SHA256_HEX = /^[0-9a-f]{64}$/;

function sha256(value: string): Buffer {
	return createHash("sha256").update(value, "utf8").digest();
}

/** 16 進表記のハッシュを Buffer にする。形式が違うものは捨てる */
export function parseTokenHashes(hashes: readonly string[]): Buffer[] {
	return hashes
		.map((hash) => hash.trim().toLowerCase())
		.filter((hash) => SHA256_HEX.test(hash))
		.map((hash) => Buffer.from(hash, "hex"));
}

/**
 * パスが接頭辞に一致するかを、区切りの / 単位で判定する。
 * `/channels` は `/channels` と `/channels/slack` に一致し、`/channelsx` には一致しない。
 */
export function matchesPathPrefix(pathname: string, prefix: string): boolean {
	const normalized = prefix.startsWith("/") ? prefix : `/${prefix}`;
	if (normalized === "/") return true;
	const base = normalized.endsWith("/") ? normalized.slice(0, -1) : normalized;
	return pathname === base || pathname.startsWith(`${base}/`);
}

function bearerToken(request: Request): string | undefined {
	const header = request.headers.get("authorization");
	if (!header) return undefined;
	const match = /^Bearer[ \t]+(\S+)[ \t]*$/i.exec(header);
	return match?.[1];
}

/** トークンのハッシュをすべての登録値と比べる。途中で打ち切らず、比較の時間を一定にする */
function tokenMatches(token: string, hashes: readonly Buffer[]): boolean {
	const digest = sha256(token);
	let matched = false;
	for (const hash of hashes) {
		if (timingSafeEqual(digest, hash)) matched = true;
	}
	return matched;
}

function unauthorized(request: Request, detail: string): Response {
	const problem = toProblem(
		new AppError(401, "unauthorized", "Unauthorized", { detail }),
		new URL(request.url).pathname,
	);
	return new Response(JSON.stringify(problem), {
		status: 401,
		headers: {
			"content-type": PROBLEM_CONTENT_TYPE,
			"www-authenticate": 'Bearer realm="rouar"',
			"cache-control": "no-store",
		},
	});
}

/**
 * アクセスの検査を作る。通すときは undefined を、拒むときは 401 の応答を返す。
 * ハッシュが 1 つも登録されていなければ、公開パス以外をすべて拒む。
 */
export function createAccessGate(
	options: AccessGateOptions,
): (request: Request) => Response | undefined {
	const hashes = parseTokenHashes(options.tokenHashes);
	const publicPaths = [...options.publicPaths];
	return (request) => {
		if (options.public) return undefined;
		const { pathname } = new URL(request.url);
		if (publicPaths.some((prefix) => matchesPathPrefix(pathname, prefix))) {
			return undefined;
		}
		const token = bearerToken(request);
		if (token === undefined) {
			return unauthorized(
				request,
				"Send the deployment access token as Authorization: Bearer <token>.",
			);
		}
		if (!tokenMatches(token, hashes)) {
			return unauthorized(request, "The access token is not valid.");
		}
		return undefined;
	};
}

/** ヘルスチェックの応答。draft-inadarei-api-health-check の形にする */
export function healthResponse(method: string): Response {
	const body = method === "HEAD" ? null : JSON.stringify({ status: "pass" });
	return new Response(body, {
		status: 200,
		headers: {
			"content-type": "application/health+json; charset=utf-8",
			"cache-control": "no-store",
		},
	});
}

export type FetchHandler = (
	request: Request,
	bindings?: unknown,
) => Response | Promise<Response>;

/**
 * Flue アプリの fetch に、ヘルスチェック、入口の検査、アクセスの検査をかぶせる。
 * ヘルスチェックは実行基盤が入口を通さずに確かめるので、入口の検査より前に答える。
 * admitFromEdge が undefined を返した要求は入口を通っていないので 404 にし、
 * 返した要求を先へ渡す。createEdgeAdmission がトークンのヘッダーを外し、URL を利用者側のものに直す。
 * アクセスの検査で断った要求は、browser があれば許可の関数で確かめ直す。
 * onAdmitted は検査を通った要求でだけ呼ぶ。ヘルスチェックと拒んだ要求では呼ばない
 */
export function createRouarFetch(
	appFetch: FetchHandler,
	gate: (request: Request) => Response | undefined,
	onAdmitted?: (request: Request, bindings: unknown) => void,
	admitFromEdge: (request: Request) => Request | undefined = withoutEdgeToken,
	browser?: BrowserAccess,
): FetchHandler {
	return async (incoming, bindings) => {
		const { pathname } = new URL(incoming.url);
		if (
			pathname === HEALTH_PATH &&
			(incoming.method === "GET" || incoming.method === "HEAD")
		) {
			return healthResponse(incoming.method);
		}
		const admitted = admitFromEdge(incoming);
		if (!admitted) return edgeNotFound();
		// 呼び出し元の見出しは SDK だけが付ける。利用者が送った値はどの経路でも捨てる
		const request = withoutPrincipalHeader(admitted);
		const denied = gate(request);
		if (!denied) {
			onAdmitted?.(request, bindings);
			return appFetch(request, bindings);
		}
		if (!browser) return denied;
		const browserAdmission = await browser.admit(
			request,
			nodeContext(bindings),
		);
		if (browserAdmission === undefined) return denied;
		if (browserAdmission instanceof Response) return browserAdmission;
		onAdmitted?.(browserAdmission.request, bindings);
		return browserAdmission.finish(
			await appFetch(browserAdmission.request, bindings),
		);
	};
}

/** @hono/node-server が渡す Node の要求と応答を、許可の関数に渡す形にする */
function nodeContext(bindings: unknown): BrowserAuthorizeContext {
	const node = bindings as
		| { incoming?: IncomingMessage; outgoing?: ServerResponse }
		| undefined;
	if (!node?.incoming || !node.outgoing) return {};
	return { node: { req: node.incoming, res: node.outgoing } };
}
