import { type Logger, type LoggerOptions, pino } from "pino";

export type { Logger };

export type CreateLoggerOptions = {
	/** ログを出すアプリやパッケージの名前 */
	name: string;
	level?: LoggerOptions["level"];
};

/** 秘密の値をログに残さないために、既定で伏せるキー */
const REDACT_PATHS = [
	"password",
	"token",
	"secret",
	"authorization",
	"*.password",
	"*.token",
	"*.secret",
	"*.authorization",
	"req.headers.authorization",
	"req.headers.cookie",
];

/** pino のロガーを作る。出力は JSON の 1 行で、集約先での検索を前提にする */
export function createLogger({ name, level }: CreateLoggerOptions): Logger {
	return pino({
		name,
		level: level ?? "info",
		redact: { paths: REDACT_PATHS, censor: "[redacted]" },
	});
}
