import { createEnv } from "@t3-oss/env-core";
import { z } from "zod";
import { secureUrl } from "./url";

/** カンマ区切りの値を、空の要素を除いた配列にする */
const commaList = z
	.string()
	.optional()
	.transform((value) =>
		(value ?? "")
			.split(",")
			.map((item) => item.trim())
			.filter((item) => item.length > 0),
	);

/** @rouar/sdk のサーバーエントリが実行時に読む環境変数 */
export function loadSdkServerEnv(
	runtimeEnv: Record<string, string | undefined> = process.env,
) {
	return createEnv({
		server: {
			PORT: z.coerce.number().int().positive().default(8080),
			LOG_LEVEL: z
				.enum(["fatal", "error", "warn", "info", "debug", "trace"])
				.default("info"),
			// ビルド済みの Flue アプリ。相対パスは作業ディレクトリから解決する
			ROUAR_APP_ENTRY: z.string().default("dist/app.mjs"),
			DATABASE_URL: z.string().optional(),
			// 実行時のプロキシ。モデルは ROUAR_GATEWAY_URL/models/v1 に向ける
			// Rouar が入れる値。ROUAR_TOKEN を送る先なので https に限る
			ROUAR_GATEWAY_URL: secureUrl.optional(),
			ROUAR_API_URL: secureUrl.optional(),
			ROUAR_VM_URL: secureUrl.optional(),
			ROUAR_TOKEN: z.string().optional(),
			ROUAR_MODELS: z.string().optional(),
			ROUAR_ACCESS_TOKEN_HASHES: commaList,
			ROUAR_PUBLIC: z
				.string()
				.optional()
				.transform((value) => value?.trim().toLowerCase() === "true"),
			ROUAR_PUBLIC_PATHS: commaList,
			// 入口が x-rouar-edge-token に付ける値。あれば、一致しない要求をヘルスチェックのほかは 404 にする。
			// Rouar が入れる値で、なければ入口を通らない要求も受ける
			ROUAR_EDGE_TOKEN: z.string().optional(),
			ROUAR_IDLE_TIMEOUT_SECONDS: z.coerce.number().int().min(0).default(600),
			// 会話の id を呼び出し元ごとに分ける鍵の材料に使う。Rouar が入れる値
			ROUAR_ENVIRONMENT_ID: z.string().optional(),
			// 許可の関数で通したブラウザからの送信の上限。利用者が変えられる
			ROUAR_BROWSER_SENDS_PER_MINUTE: z.coerce
				.number()
				.int()
				.positive()
				.default(10),
			ROUAR_BROWSER_SENDS_PER_DAY: z.coerce
				.number()
				.int()
				.positive()
				.default(200),
			ROUAR_BROWSER_ENVIRONMENT_SENDS_PER_DAY: z.coerce
				.number()
				.int()
				.positive()
				.default(5000),
			// Rouar が入れる値。環境を常に動かす設定にしたときだけ true で、暇な間に自分で止まらない
			ROUAR_ALWAYS_ON: z
				.string()
				.optional()
				.transform((value) => value?.trim().toLowerCase() === "true"),
		},
		runtimeEnv,
		emptyStringAsUndefined: true,
	});
}

export type SdkServerEnv = ReturnType<typeof loadSdkServerEnv>;
