import { readFile } from "node:fs/promises";
import type { IncomingMessage, ServerResponse } from "node:http";
import { isAbsolute, join, relative, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import type { Logger } from "@rouar/log";
import { z } from "zod";
import { DEFAULT_AGENT_ROUTES } from "../config";
import { createStaticHandler, type NodeHandler } from "./static";

/** デプロイのイメージで、ワーカーがフロントエンドの成果物と frontend.json を置く場所 */
export const DEFAULT_FRONTEND_DIR = "/app/.rouar/frontend";

/** frontend.json のファイル名 */
export const FRONTEND_MANIFEST = "frontend.json";

/** エージェントへ渡すパスの接頭辞の既定。rouar.json の agent.routes の既定と同じものを使う */
export { DEFAULT_AGENT_ROUTES };

/** 成果物の中のパス。frontend.json のあるディレクトリからの相対パスに限る */
const innerPath = z
	.string()
	.min(1)
	.refine((value) => !isAbsolute(value) && !value.includes("\0"), {
		message: "must be a relative path",
	});

/**
 * ワーカーがビルドのあとに書く frontend.json の形。
 * 知らない項目は無視し、ワーカーが先に項目を足しても起動できるようにする
 */
export const frontendManifestSchema = z.discriminatedUnion("mode", [
	z.object({
		framework: z.enum(["nuxt", "vue-vite", "sveltekit", "react-vite"]),
		mode: z.literal("ssr"),
		/** Node の listener を export するファイル。Nuxt なら server/index.mjs */
		entry: innerPath,
		/**
		 * SSR のサーバーより先に返す静的なファイルのディレクトリ。Nuxt なら public。
		 * Nitro の node-listener は serveStatic を持たず、.output/public を自分では返さない
		 */
		publicDir: innerPath.optional(),
		agentRoutes: z.array(z.string().min(1)).optional(),
	}),
	z.object({
		framework: z.enum(["nuxt", "vue-vite", "sveltekit", "react-vite"]),
		mode: z.literal("static"),
		/** 静的なファイルのディレクトリ。Nuxt なら public、Vite なら dist の中身を置いたところ */
		publicDir: innerPath,
		agentRoutes: z.array(z.string().min(1)).optional(),
	}),
]);

export type FrontendManifest = z.infer<typeof frontendManifestSchema>;

export type Frontend = {
	manifest: FrontendManifest;
	/** エージェントへ渡すパスの接頭辞 */
	agentRoutes: string[];
	/** エージェントの経路でない要求を返す */
	handle: NodeHandler;
};

/** 名前にハッシュの入ったファイルを置く接頭辞。フレームワークのビルドの既定に合わせる */
function immutablePrefixes(framework: FrontendManifest["framework"]): {
	immutablePrefixes: string[];
	mutablePrefixes: string[];
} {
	if (framework === "nuxt") {
		// _nuxt/builds/latest.json は名前にハッシュがなく、デプロイのたびに中身が変わる
		return {
			immutablePrefixes: ["/_nuxt/"],
			mutablePrefixes: ["/_nuxt/builds/"],
		};
	}
	if (framework === "sveltekit") {
		return { immutablePrefixes: ["/_app/immutable/"], mutablePrefixes: [] };
	}
	return { immutablePrefixes: ["/assets/"], mutablePrefixes: [] };
}

/** 成果物の中のパスを絶対パスにする。ディレクトリの外を指せば例外にする */
function insideDir(dir: string, path: string): string {
	const absolute = resolve(dir, path);
	const rel = relative(dir, absolute);
	if (rel.startsWith("..") || isAbsolute(rel)) {
		throw new Error(`[rouar] ${FRONTEND_MANIFEST} points outside ${dir}`);
	}
	return absolute;
}

type NodeListenerModule = {
	listener?: unknown;
	handler?: unknown;
	default?: unknown;
};

type NodeListener = (
	request: IncomingMessage,
	response: ServerResponse,
) => unknown;

const TRAPPED_EVENTS = ["uncaughtException", "unhandledRejection"] as const;

/** process の型は event ごとの多重定義で、名前の配列から引けないので EventEmitter として扱う */
const processEvents = process as unknown as NodeJS.EventEmitter;

/**
 * Nitro の node-listener の成果物を読み込み、listener を返す。
 * Nitro は読み込みのときに uncaughtException と unhandledRejection の handler を process に足し、
 * 例外を記録してプロセスを落とさない。SSR の不具合で同じプロセスのエージェントを落とさないよう、この handler は残す。
 * そのうえで、足された handler を SDK のログに残す包みに置き換え、何が起きたかを利用者のログで追えるようにする。
 * Nitro はシグナルを扱わないので、SIGTERM と暇な間の停止は今までどおり SDK の入口が process.exit で終える。
 * Nitro を別のプロセスに移すときに差し替えられるよう、Nitro を読むところはこの関数だけにする
 */
export async function loadNodeListener(
	entry: string,
	logger: Logger,
): Promise<NodeListener> {
	const before = new Map(
		TRAPPED_EVENTS.map((event) => [
			event,
			new Set(processEvents.listeners(event)),
		]),
	);
	const mod = (await import(pathToFileURL(entry).href)) as NodeListenerModule;
	for (const event of TRAPPED_EVENTS) {
		const existing = before.get(event) ?? new Set();
		for (const added of processEvents.listeners(event)) {
			if (existing.has(added)) continue;
			const original = added as (...args: unknown[]) => void;
			processEvents.removeListener(event, original);
			processEvents.on(event, (...args: unknown[]) => {
				logger.error(
					{ err: args[0], event },
					"unhandled error in the process; the server keeps running",
				);
				// 包みから例外を投げると Node がプロセスを落とすので、元の handler の失敗もログだけにする
				try {
					original(...args);
				} catch (error) {
					logger.error({ err: error, event }, "process error handler failed");
				}
			});
		}
	}
	const listener = [mod.listener, mod.handler, mod.default].find(
		(candidate): candidate is NodeListener => typeof candidate === "function",
	);
	if (!listener) {
		throw new Error(
			`[rouar] ${entry} does not export a Node listener. Build the frontend server for a Node listener target.`,
		);
	}
	return listener;
}

/** listener が投げたか、応答を始める前に失敗したときの応答。中身はログにだけ残す */
function wrapListener(listener: NodeListener, logger: Logger): NodeHandler {
	return async (request, response) => {
		try {
			await listener(request, response);
		} catch (error) {
			logger.error({ err: error }, "frontend server failed");
			if (!response.headersSent) {
				response.writeHead(500, {
					"content-type": "text/plain; charset=utf-8",
					"cache-control": "no-store",
				});
				response.end("internal server error\n");
			} else {
				response.destroy();
			}
		}
	};
}

/**
 * frontend.json を読み、フロントエンドを返す handler を作る。
 * frontend.json がなければ、フロントエンドのない環境として undefined を返す。
 * 形が合わないか、SSR の成果物を読み込めなければ例外にし、デプロイを失敗させる
 */
export async function loadFrontend(
	dir: string,
	logger: Logger,
): Promise<Frontend | undefined> {
	const root = resolve(dir);
	let text: string;
	try {
		text = await readFile(join(root, FRONTEND_MANIFEST), "utf8");
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
		throw error;
	}
	const parsed = frontendManifestSchema.safeParse(JSON.parse(text));
	if (!parsed.success) {
		throw new Error(
			`[rouar] ${FRONTEND_MANIFEST} is not valid: ${parsed.error.issues
				.map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`)
				.join("; ")}`,
		);
	}
	const manifest = parsed.data;
	const agentRoutes = manifest.agentRoutes ?? [...DEFAULT_AGENT_ROUTES];
	if (manifest.mode === "ssr") {
		const listener = await loadNodeListener(
			insideDir(root, manifest.entry),
			logger,
		);
		const server = wrapListener(listener, logger);
		const handle = manifest.publicDir
			? createStaticHandler({
					root: insideDir(root, manifest.publicDir),
					...immutablePrefixes(manifest.framework),
					fallthrough: server,
				})
			: server;
		return { manifest, agentRoutes, handle };
	}
	const handle = createStaticHandler({
		root: insideDir(root, manifest.publicDir),
		...immutablePrefixes(manifest.framework),
	});
	return { manifest, agentRoutes, handle };
}
