import { createServer, type Server } from "node:http";
import type { AddressInfo } from "node:net";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { getRequestListener } from "@hono/node-server";
import { loadSdkServerEnv } from "@rouar/env/sdk";
import { createLogger, type Logger } from "@rouar/log";
import pg from "pg";
import { registerInProcessAgentFetch } from "../access";
import { getUnsettledSubmissionsProbe } from "../persistence-probe";
import { createBrowserAccess, selectTagKey } from "./browser";
import { createEdgeAdmission, createNodeEdgeAdmission } from "./edge";
import {
	DEFAULT_AGENT_ROUTES,
	DEFAULT_FRONTEND_DIR,
	loadFrontend,
} from "./frontend";
import { createAccessGate, createRouarFetch, parseTokenHashes } from "./gate";
import {
	createAdmissionTracker,
	createIdleMonitor,
	idleTimeoutMs,
	type ResponseCloseEmitter,
} from "./idle";
import { startEventLoopLagMonitor } from "./lag";
import { registerRouarProvider } from "./providers";
import { createRouarListener } from "./router";

/** Flue の dist/app.mjs が返すアプリのうち、ここで使うもの */
export type FlueNodeApplication = {
	fetch(request: Request, env?: unknown): Response | Promise<Response>;
	pauseAdmissions(): void;
	stop(timeoutMs?: number): Promise<void>;
	closeSync(): void;
};

type FlueAppModule = {
	loadFlueNodeApplication?: (options?: {
		env?: Record<string, string | undefined>;
	}) => Promise<FlueNodeApplication>;
};

export type StartRouarServerOptions = {
	env?: Record<string, string | undefined>;
	cwd?: string;
	/** 0 を渡すと空いているポートを使う */
	port?: number;
	hostname?: string;
	logger?: Logger;
	/** フロントエンドの成果物と frontend.json の場所。既定はデプロイのイメージの /app/.rouar/frontend */
	frontendDir?: string;
};

export type RouarServer = {
	server: Server;
	port: number;
	/** 新しい仕事の受け付けを止め、Flue の終了処理を待ってから閉じる */
	shutdown(reason: string): Promise<void>;
	/** アイドル停止の条件を満たしたときに解決する */
	idle: Promise<void>;
};

/** Flue の終了処理に渡す時間。実行基盤が強制終了する 60 秒に収める */
const FLUE_STOP_TIMEOUT_MS = 45_000;

/** アイドル判定でデータベースに問い合わせるときの上限 */
const PROBE_TIMEOUT_MS = 5000;

const UNSETTLED_SQL =
	"SELECT 1 FROM flue_agent_submissions WHERE status IN ('queued', 'running', 'terminalizing', 'joining', 'joined') LIMIT 1";

/** DATABASE_URL から flue_agent_submissions を直接見る。読めなければ undefined を返す */
function createDatabaseProbe(connectionString: string) {
	let pool: pg.Pool | undefined;
	return {
		async query(): Promise<boolean | undefined> {
			try {
				pool ??= new pg.Pool({
					connectionString,
					max: 1,
					// 届かないデータベースで判定を止めない
					connectionTimeoutMillis: PROBE_TIMEOUT_MS,
					query_timeout: PROBE_TIMEOUT_MS,
				});
				const result = await pool.query(UNSETTLED_SQL);
				return result.rowCount !== null && result.rowCount > 0;
			} catch {
				return undefined;
			}
		},
		async close() {
			const current = pool;
			pool = undefined;
			await current?.end().catch(() => undefined);
		},
	};
}

export async function loadFlueApplication(
	entry: string,
	cwd: string,
	env: Record<string, string | undefined>,
): Promise<FlueNodeApplication> {
	const href = pathToFileURL(resolve(cwd, entry)).href;
	const mod = (await import(href)) as FlueAppModule;
	if (typeof mod.loadFlueNodeApplication !== "function") {
		throw new Error(
			`[rouar] ${entry} does not export loadFlueNodeApplication. Build the Flue app with \`vite build\` for the Node target.`,
		);
	}
	return mod.loadFlueNodeApplication({ env });
}

/**
 * Rouar のサーバーを起動する。
 * provider を登録してから Flue のアプリを読み込み、アクセスの検査とヘルスチェックをかぶせて配信する。
 */
export async function startRouarServer(
	options: StartRouarServerOptions = {},
): Promise<RouarServer> {
	const runtimeEnv = options.env ?? process.env;
	const env = loadSdkServerEnv(runtimeEnv);
	const cwd = options.cwd ?? process.cwd();
	const logger =
		options.logger ?? createLogger({ name: "rouar-sdk", level: env.LOG_LEVEL });

	// Flue の組み込みの provider より前に登録する。利用者の app.ts での登録はこれを上書きできる
	let models: string[] = [];
	try {
		models = registerRouarProvider(env);
	} catch (error) {
		logger.error({ err: error }, "ROUAR_MODELS could not be read");
	}
	if (models.length > 0) {
		logger.info({ models }, "registered custom models for provider rouar");
	}

	// Nitro の読み込みを Flue のアプリの読み込みと重ね、起動を待つ時間を減らす
	const [app, frontend] = await Promise.all([
		loadFlueApplication(env.ROUAR_APP_ENTRY, cwd, runtimeEnv),
		loadFrontend(
			resolve(cwd, options.frontendDir ?? DEFAULT_FRONTEND_DIR),
			logger,
		),
	]);
	if (frontend) {
		logger.info(
			{
				framework: frontend.manifest.framework,
				mode: frontend.manifest.mode,
				agentRoutes: frontend.agentRoutes,
			},
			"serving the frontend alongside the agent",
		);
	}

	const gate = createAccessGate({
		tokenHashes: env.ROUAR_ACCESS_TOKEN_HASHES,
		public: env.ROUAR_PUBLIC,
		publicPaths: env.ROUAR_PUBLIC_PATHS,
	});
	const validHashes = parseTokenHashes(env.ROUAR_ACCESS_TOKEN_HASHES).length;
	const malformedHashes = env.ROUAR_ACCESS_TOKEN_HASHES.length - validHashes;
	if (malformedHashes > 0) {
		// 値そのものは記録しない
		logger.warn(
			{ count: malformedHashes },
			"ignored malformed entries in ROUAR_ACCESS_TOKEN_HASHES",
		);
	}
	if (!env.ROUAR_PUBLIC && validHashes === 0) {
		logger.warn(
			"no ROUAR_ACCESS_TOKEN_HASHES and ROUAR_PUBLIC is not true; agent routes reject every request",
		);
	}

	const databaseProbe = env.DATABASE_URL
		? createDatabaseProbe(env.DATABASE_URL)
		: undefined;
	const canProbe =
		getUnsettledSubmissionsProbe() !== undefined || databaseProbe !== undefined;
	const hasUnsettled = async (): Promise<boolean | undefined> => {
		const registered = getUnsettledSubmissionsProbe();
		if (registered) return registered();
		return databaseProbe?.query();
	};

	let resolveIdle!: () => void;
	const idle = new Promise<void>((resolve) => {
		resolveIdle = resolve;
	});
	if (env.ROUAR_ALWAYS_ON) {
		logger.info("idle self-stop is disabled because ROUAR_ALWAYS_ON is true");
	} else if (!canProbe && env.ROUAR_IDLE_TIMEOUT_SECONDS > 0) {
		logger.info(
			"idle self-stop is disabled because unfinished submissions cannot be checked",
		);
	}
	const monitor = createIdleMonitor({
		timeoutMs: idleTimeoutMs({
			timeoutSeconds: env.ROUAR_IDLE_TIMEOUT_SECONDS,
			alwaysOn: env.ROUAR_ALWAYS_ON,
			canProbe,
		}),
		inFlight: () => tracker.inFlight(),
		hasUnsettled,
		onIdle: () => resolveIdle(),
	});
	// 検査を通った要求だけを数える。ヘルスチェックと 401 ではアイドル停止を先送りしない。
	// フロントエンドの要求も数え、表示されている間はマシンを止めない
	const tracker = createAdmissionTracker(() => monitor.touch());
	// 許可の関数は要求ごとに登録先から読む。Flue の app.ts も Nuxt のモジュールも、読み込みの順を気にせず登録できる
	const browser = createBrowserAccess({
		agentRoutes: frontend?.agentRoutes ?? DEFAULT_AGENT_ROUTES,
		tagKey: selectTagKey(env, logger),
		limits: {
			perMinute: env.ROUAR_BROWSER_SENDS_PER_MINUTE,
			perDay: env.ROUAR_BROWSER_SENDS_PER_DAY,
			environmentPerDay: env.ROUAR_BROWSER_ENVIRONMENT_SENDS_PER_DAY,
		},
		logger,
	});
	const handler = createRouarFetch(
		(request) => app.fetch(request),
		gate,
		(_request, bindings) =>
			tracker.admit(
				(bindings as { outgoing?: ResponseCloseEmitter } | undefined)?.outgoing,
			),
		createEdgeAdmission(env.ROUAR_EDGE_TOKEN),
		browser,
	);
	// フロントエンドのサーバーのコードが agentFetch で呼ぶ。入口とアクセスの検査は通さない
	registerInProcessAgentFetch(async (request, principal) => {
		const scoped = browser.scope(request, principal);
		if (scoped instanceof Response) return scoped;
		return app.fetch(scoped);
	});

	const agentListener = getRequestListener(handler, {
		...(options.hostname ? { hostname: options.hostname } : {}),
	});
	// フロントエンドがなければ、今までどおりすべての要求を Flue の側に渡す
	const listener = frontend
		? createRouarListener({
				agent: agentListener,
				frontend: frontend.handle,
				// ROUAR_PUBLIC_PATHS の接頭辞も、Slack などの受け口なのでエージェントへ渡す
				agentRoutes: [...frontend.agentRoutes, ...env.ROUAR_PUBLIC_PATHS],
				admitFromEdge: createNodeEdgeAdmission(env.ROUAR_EDGE_TOKEN),
				onAdmitted: (response) => tracker.admit(response),
			})
		: agentListener;
	const lag = startEventLoopLagMonitor({ logger });

	const port = options.port ?? env.PORT;
	// SSE や long-poll を切らない
	const server = createServer({ requestTimeout: 0 }, listener);
	await new Promise<void>((resolveServer, rejectServer) => {
		server.once("error", rejectServer);
		server.listen(port, options.hostname, () => {
			server.off("error", rejectServer);
			resolveServer();
		});
	});
	const listeningPort = (server.address() as AddressInfo).port;
	logger.info({ port: listeningPort }, "rouar server listening");

	let stopping: Promise<void> | undefined;
	const shutdown = (reason: string): Promise<void> => {
		if (stopping) return stopping;
		stopping = (async () => {
			logger.info({ reason }, "shutting down");
			monitor.stop();
			lag.stop();
			app.pauseAdmissions();
			registerInProcessAgentFetch(undefined);
			const httpClosed = new Promise<void>((resolveClosed) =>
				server.close(() => resolveClosed()),
			);
			try {
				await app.stop(FLUE_STOP_TIMEOUT_MS);
			} catch (error) {
				logger.error({ err: error }, "flue shutdown failed");
			}
			server.closeAllConnections();
			await httpClosed;
			await databaseProbe?.close();
		})();
		return stopping;
	};

	return { server, port: listeningPort, shutdown, idle };
}
