import type { IncomingMessage, ServerResponse } from "node:http";
import { edgeNotFound, type NodeEdgeRequest } from "./edge";
import { HEALTH_PATH, matchesPathPrefix } from "./gate";
import { type NodeHandler, requestPath } from "./static";

export type RouarListenerOptions = {
	/** Flue のアプリに、ヘルスチェック、入口の検査、アクセスの検査をかぶせた listener */
	agent: (request: IncomingMessage, response: ServerResponse) => unknown;
	/** フロントエンドを返す handler */
	frontend: NodeHandler;
	/** エージェントへ渡すパスの接頭辞。agent.routes と ROUAR_PUBLIC_PATHS を合わせたもの */
	agentRoutes: readonly string[];
	/** createNodeEdgeAdmission の結果。入口を通っていなければ false を返す */
	admitFromEdge: (request: NodeEdgeRequest) => boolean;
	/** 入口の検査を通ったフロントエンドの要求で呼ぶ。暇な間の停止の数に入れる */
	onAdmitted?: (response: ServerResponse) => void;
};

async function sendResponse(
	response: ServerResponse,
	fetched: Response,
): Promise<void> {
	response.writeHead(fetched.status, Object.fromEntries(fetched.headers));
	response.end(await fetched.text());
}

/**
 * Node の HTTP のサーバーの段で、エージェントとフロントエンドに振り分ける listener を作る。
 * ヘルスチェックとエージェントの経路は、今までと同じ検査を通す agent に渡す。
 * そのほかは入口の検査だけをして frontend に渡す。フロントエンドからは Flue を呼べないので、アクセスの検査は要らない
 */
export function createRouarListener(
	options: RouarListenerOptions,
): (request: IncomingMessage, response: ServerResponse) => Promise<void> {
	return async (request, response) => {
		const pathname = requestPath(request);
		if (
			pathname === HEALTH_PATH ||
			options.agentRoutes.some((prefix) => matchesPathPrefix(pathname, prefix))
		) {
			await options.agent(request, response);
			return;
		}
		if (!options.admitFromEdge(request)) {
			await sendResponse(response, edgeNotFound());
			return;
		}
		options.onAdmitted?.(response);
		await options.frontend(request, response);
	};
}
