/** RFC 9457 の Problem Details の本文 */
export type Problem = {
	type: string;
	title: string;
	status: number;
	detail?: string;
	instance?: string;
};

export const PROBLEM_CONTENT_TYPE = "application/problem+json; charset=utf-8";

const PROBLEM_TYPE_BASE = "https://rouar.com/problems/";

/** アプリの中で投げ、境界で Problem Details に変換するエラー */
export class AppError extends Error {
	readonly status: number;
	readonly code: string;
	readonly detail?: string;

	constructor(
		status: number,
		code: string,
		title: string,
		options?: { detail?: string; cause?: unknown },
	) {
		super(title, { cause: options?.cause });
		this.name = "AppError";
		this.status = status;
		this.code = code;
		this.detail = options?.detail;
	}
}

/** エラーを Problem Details に変換する。AppError 以外は中身を出さずに 500 にする */
export function toProblem(error: unknown, instance?: string): Problem {
	if (error instanceof AppError) {
		return {
			type: `${PROBLEM_TYPE_BASE}${error.code}`,
			title: error.message,
			status: error.status,
			...(error.detail === undefined ? {} : { detail: error.detail }),
			...(instance === undefined ? {} : { instance }),
		};
	}
	return {
		type: `${PROBLEM_TYPE_BASE}internal`,
		title: "Internal server error",
		status: 500,
		...(instance === undefined ? {} : { instance }),
	};
}
